            "title": "Témoignage : De l'université au premier emploi",
            "content": "« Après ma licence de langues étrangères appliquées à Lyon, je me suis posé mille questions sur mon avenir. Les cours théoriques m'avaient passionné, mais je manquais cruellement d'expérience concrète pour intégrer le marché du travail.<br><br>C'est pourquoi j'ai décidé de postuler à un master professionnel en alternance spécialisé dans le commerce international. Pendant deux ans, j'ai partagé mes semaines entre les amphithéâtres de la faculté et les bureaux d'une entreprise lyonnaise d export de produits gastronomiques.<br><br>Ce rythme exigeant m'a appris à gérer mon temps, à travailler en équipe et à négocier avec des partenaires étrangers. Grâce à cette expérience humaine et professionnelle, mon tuteur m'a proposé un poste de chef de projet junior dès le lendemain de ma soutenance de mémoire. Ce fut un immense soulagement et une grande fierté ! »",
            "audioText": "Après ma licence de langues étrangères appliquées à Lyon, je me suis posé mille questions sur mon avenir. Les cours théoriques m'avaient passionné, mais je manquais cruellement d'expérience concrète pour intégrer le marché du travail. C'est pourquoi j'ai décidé de postuler à un master professionnel en alternance spécialisé dans le commerce international. Pendant deux ans, j'ai partagé mes semaines entre les amphithéâtres de la faculté et les bureaux d'une entreprise lyonnaise d export de produits gastronomiques. Ce rythme exigeant m'a appris à gérer mon temps, à travailler en équipe et à négocier avec des partenaires étrangers. Grâce à cette expérience humaine et professionnelle, mon tuteur m'a proposé un poste de chef de projet junior dès le lendemain de ma soutenance de mémoire. Ce fut un immense soulagement et une grande fierté !"
