            "type": "lesson",
            "title": "Témoignage : L'expérience de l habitat participatif",
            "content": "« Après dix années passées dans un petit studio parisien impersonnel, nous rêvions d'un cadre de vie plus solidaire pour élever notre fille. Nous avons alors rejoint une aventure d habitat participatif en périphérie de Rennes.<br><br>Le principe est simple mais exigeant : dix familles se sont réunies pour concevoir ensemble un immeuble écologique en bois et paille. Chaque foyer dispose de son propre appartement indépendant, mais nous partageons plusieurs espaces communs : une grande buanderie, un atelier de bricolage, une chambre d'amis pour recevoir nos proches et un immense potager sur le toit.<br><br>Ce choix implique des réunions régulières et une écoute mutuelle constante, mais la richesse des échanges compense largement les petits désaccords. Vivre ici, c'est retrouver le sens du collectif sans renoncer à son intimité. »",
            "audioText": "Après dix années passées dans un petit studio parisien impersonnel, nous rêvions d'un cadre de vie plus solidaire pour élever notre fille. Nous avons alors rejoint une aventure d habitat participatif en périphérie de Rennes. Le principe est simple mais exigeant : dix familles se sont réunies pour concevoir ensemble un immeuble écologique en bois et paille. Chaque foyer dispose de son propre appartement indépendant, mais nous partageons plusieurs espaces communs : une grande buanderie, un atelier de bricolage, une chambre d'amis pour recevoir nos proches et un immense potager sur le toit. Ce choix implique des réunions régulières et une écoute mutuelle constante, mais la richesse des échanges compense largement les petits désaccords. Vivre ici, c'est retrouver le sens du collectif sans renoncer à son intimité."
