            "title": "Étape 5 : 📖 Récit de situation — L'art de gérer l'imprévu : mésaventures et résolutions",
            "content": "**L'art de gérer l'imprévu : Chronique d'un dimanche mouvementé à Lyon**\n\nCe dimanche-là, Antoine avait minutieusement préparé son emploi du temps : assister le matin à l'anniversaire de sa sœur dans la banlieue lyonnaise, puis prendre le TGV de dix-sept heures vers Paris pour un entretien d'embauche capital le lendemain à la première heure. Mais comme le rappelle souvent l'adage populaire, ce sont précisément les imprévus qui révèlent notre sens de l'adaptation et notre maîtrise de la situation.\n\nLe premier accroc survint dès midi. En sortant de la station de métro, Antoine s'aperçut avec stupeur que la fermeture éclair de sa sacoche était ouverte : son portefeuille contenant ses cartes bancaires et sa pièce d'identité avait disparu. Pris d'un vertige momentané, il respira profondément et fit appel à son sang-froid. Plutôt que de céder à l'affolement, il se connecta sans attendre à l'application de sa banque sur son smartphone pour faire opposition sur ses moyens de paiement. Dans la foulée, il se rendit au commissariat du troisième arrondissement pour effectuer une déclaration officielle de perte, document indispensable pour pouvoir embarquer à bord d'un train en cas de contrôle d'identité.\n\nArrivé à la gare de Lyon-Part-Dieu à seize heures trente, une seconde épreuve l'attendait sur les panneaux d'affichage géants : en raison d'un violent orage ayant endommagé les caténaires en Bourgogne, son train était purement et simplement supprimé, et les rames suivantes affichaient complet pour le reste de la soirée. Pour Antoine, rater cet entretien parisien était impensable.\n\nAu lieu d'agresser verbalement les agents d'accueil débordés de questions, Antoine adopta une tactique beaucoup plus constructive. Il se présenta au comptoir d'information avec un sourire calme et courtois : « Bonjour Madame. Je comprends parfaitement que vous fassiez face à une situation complexe et indépendante de votre volonté. Néanmoins, ma présence à Paris demain matin est impérative pour mon avenir professionnel. Existerait-il une alternative par TER via Dijon, ou une navette d'autocars mise en place pour les voyageurs en correspondance prioritaire ? »\n\nTouchée par son empathie et son ton mesuré, l'agente prit le temps d'étudier les correspondances régionales. Elle lui dénicha une place de dernière minute sur un car express reliant Lyon à Paris Bercy durant la nuit. Arrivé à l'aube dans la capitale, frais et dispos après un café bien serré, Antoine réussit brillamment son entretien, ayant prouvé avant même d'être recruté sa remarquable capacité à transformer un obstacle en succès.",
