            "title": "Témoignage : Ma méthode pour m'informer sereinement",
            "content": "« Depuis quelques années, le flux continu des notifications sur mon smartphone me provoquait un sentiment de saturation permanent. Chaque minute apportait son lot d'alertes urgentes, souvent anxiogènes et superficielles.<br><br>J'ai décidé de transformer ma manière de consommer l'actualité. D'abord, j'ai désactivé toutes les alertes instantanées. Ensuite, j'ai souscrit un abonnement à deux quotidiens reconnus pour leur rigueur déontologique, ainsi qu'à une revue mensuelle d'analyse. Au lieu de réagir à chaud à des bribes de vidéos non vérifiées, je prends désormais quarante-cinq minutes chaque soir pour lire des dossiers approfondis.<br><br>Mes proches me disent souvent que je risque de manquer une nouvelle importante en direct. Je leur réponds qu'il vaut mieux comprendre le monde avec un léger décalage que de céder à la panique ou aux fausses rumeurs. »",
            "audioText": "Depuis quelques années, le flux continu des notifications sur mon smartphone me provoquait un sentiment de saturation permanent. Chaque minute apportait son lot d'alertes urgentes, souvent anxiogènes et superficielles. J'ai décidé de transformer ma manière de consommer l'actualité. D'abord, j'ai désactivé toutes les alertes instantanées. Ensuite, j'ai souscrit un abonnement à deux quotidiens reconnus pour leur rigueur déontologique, ainsi qu'à une revue mensuelle d'analyse. Au lieu de réagir à chaud à des bribes de vidéos non vérifiées, je prends désormais quarante-cinq minutes chaque soir pour lire des dossiers approfondis. Mes proches me disent souvent que je risque de manquer une nouvelle importante en direct. Je leur réponds qu'il vaut mieux comprendre le monde avec un léger décalage que de céder à la panique ou aux fausses rumeurs."
