            "type": "lesson",
            "title": "Étape 5 : 📖 Texte intégral — Dans les coulisses de la matinale radiophonique",
            "content": "**Dans les coulisses de la matinale radiophonique**\n\nIl est cinq heures quarante-cinq dans les couloirs feutrés de la Maison de la Radio, à Paris. Tandis que la capitale dort encore sous une brume légère, le studio 221 s'anime dans une effervescence méthodique. Face à la console numérique aux dizaines de curseurs lumineux, l'équipe de rédaction prépare le grand rendez-vous de sept heures : la matinale, émission la plus écoutée de la journée.\n\nAu micro principal, Julie Morand relit ses fiches cartonnées d'un œil aguerri. À côté d'elle, le rédacteur en chef valide les derniers sujets d'actualité. « Nous ouvrons avec le plan national pour la transition écologique dans les transports ferroviaires », annonce-t-il d'une voix calme. « Ensuite, nous enchaînons avec notre envoyé spécial à Rome pour le sommet européen, puis le micro-trottoir sur les horaires d'ouverture des commerces le dimanche. »\n\nÀ la radio, chaque seconde compte. Contrairement à la presse écrite où le lecteur peut relire une phrase complexe, ou à la télévision où l'image guide le regard, l'information radiophonique repose exclusivement sur la clarté du verbe et la précision du rythme. Les phrases doivent être courtes, percutantes et accessibles à tous, qu'on écoute dans son salon, dans sa voiture au milieu des embouteillages ou sur son smartphone dans les transports en commun.\n\nSoudain, le voyant rouge s'allume : « Silence, antenne ! ». L'indicatif musical retentit. « Bonjour à tous, vous êtes bien sur Radio France Horizon. Il est sept heures, voici les titres de l'actualité... » En trois minutes, le monde se dessine à travers la voix posée de la journaliste. Écouter la radio, ce n'est pas simplement recevoir des nouvelles : c'est partager un rituel collectif où la voix humaine donne du sens à la marche du monde.",
            "audioText": "Il est cinq heures quarante-cinq dans les couloirs feutrés de la Maison de la Radio, à Paris. Tandis que la capitale dort encore sous une brume légère, le studio 221 s'anime dans une effervescence méthodique. Face à la console numérique aux dizaines de curseurs lumineux, l'équipe de rédaction prépare le grand rendez-vous de sept heures : la matinale, émission la plus écoutée de la journée. Au micro principal, Julie Morand relit ses fiches cartonnées d'un œil aguerri. À côté d'elle, le rédacteur en chef valide les derniers sujets d'actualité. Nous ouvrons avec le plan national pour la transition écologique dans les transports ferroviaires, annonce-t-il d'une voix calme. Ensuite, nous enchaînons avec notre envoyé spécial à Rome pour le sommet européen, puis le micro-trottoir sur les horaires d'ouverture des commerces le dimanche. À la radio, chaque seconde compte. Contrairement à la presse écrite où le lecteur peut relire une phrase complexe, ou à la télévision où l'image guide le regard, l'information radiophonique repose exclusivement sur la clarté du verbe et la précision du rythme. Les phrases doivent être courtes, percutantes et accessibles à tous, qu'on écoute dans son salon, dans sa voiture au milieu des embouteillages ou sur son smartphone dans les transports en commun. Soudain, le voyant rouge s'allume : Silence, antenne ! L'indicatif musical retentit. Bonjour à tous, vous êtes bien sur Radio France Horizon. Il est sept heures, voici les titres de l'actualité... En trois minutes, le monde se dessine à travers la voix posée de la journaliste. Écouter la radio, ce n'est pas simplement recevoir des nouvelles : c'est partager un rituel collectif où la voix humaine donne du sens à la marche du monde."
