            "content": "« Très timide depuis mon adolescence, j'éprouvais les plus grandes difficultés à prendre la parole devant un groupe. Un soir d'automne, une amie m'a convaincu d'assister à une répétition dans la Maison des Jeunes et de la Culture de mon quartier. J'ai découvert une troupe chaleureuse où personne ne jugeait les hésitations des débutants.<br><br>Pendant six mois, nous avons travaillé sur une comédie moderne de Molière. Chaque séance commençait par des exercices de respiration et d'articulation, avant d'aborder le jeu corporel. Le travail collectif m'a permis de surmonter progressivement mes angoisses.<br><br>Le soir de la représentation publique, quand le rideau s'est levé devant deux cents personnes, mon cœur battait à tout rompre. Dès ma première réplique, le trac a cédé la place à un plaisir immense. Le rire des spectateurs a récompensé tous nos efforts. »",
