            "type": "lesson",
            "title": "Étape 5 : 📖 Texte intégral — La lettre retrouvée au grenier",
            "content": "**La lettre retrouvée au grenier**\n\nC'était un dimanche d'automne pluvieux, de ces journées silencieuses où le vent fait danser les feuilles mortes contre les carreaux. Pour occuper l'après-midi, Mathieu avait décidé de ranger enfin le vieux grenier de la maison familiale en Bourgogne. Entre deux malles d'osier poussiéreuses et une pile d'anciens manuels de botanique, ses doigts ont frôlé une boîte métallique ornée d'arabesques usées par les décennies.\n\nÀ l'intérieur reposait un carnet relié de cuir fauve et quelques enveloppes timbrées aux bords jaunis. En dépliant la première feuille rédigée d'une écriture à la plume délicate, Mathieu a immédiatement reconnu l'écriture de sa grand-mère Madeleine, datée du printemps 1954. Elle y décrivait avec une sincérité désarmante ses premiers jours dans la capitale, partagée entre une vive appréhension devant l'immensité de Paris et l'émerveillement quotidien d'arpenter les berges de la Seine.\n\nUne vague d'émotion imprévue a submergé le jeune homme. Au fil des lignes se dessinaient les doutes d'une jeune femme de vingt ans : la peur de décevoir ses parents restés au village, la solitude des soirs d'hiver dans sa modeste chambre mansardée, mais aussi l'immense joie de réussir son premier concours d'institutrice. Madeleine écrivait : « J'ai parfois le cœur serré de vous savoir loin, mais chaque matin m'apporte la certitude que ma place est ici, auprès de ces enfants qui ont tant à apprendre. »\n\nRefermant la boîte avec d'infinies précautions, Mathieu a ressenti un profond soulagement mêlé d'une fierté nouvelle. Les émotions de sa grand-mère faisaient écho à ses propres hésitations actuelles face à ses choix de carrière. Posant le carnet sur son bureau, il a compris que nommer ses peurs et ses joies constituait le plus beau moyen de les apprivoiser et d'avancer sereinement.",
            "audioText": "C'était un dimanche d'automne pluvieux, de ces journées silencieuses où le vent fait danser les feuilles mortes contre les carreaux. Pour occuper l'après-midi, Mathieu avait décidé de ranger enfin le vieux grenier de la maison familiale en Bourgogne. Entre deux malles d'osier poussiéreuses et une pile d'anciens manuels de botanique, ses doigts ont frôlé une boîte métallique ornée d'arabesques usées par les décennies. À l'intérieur reposait un carnet relié de cuir fauve et quelques enveloppes timbrées aux bords jaunis. En dépliant la première feuille rédigée d'une écriture à la plume délicate, Mathieu a immédiatement reconnu l'écriture de sa grand-mère Madeleine, datée du printemps 1954. Elle y décrivait avec une sincérité désarmante ses premiers jours dans la capitale, partagée entre une vive appréhension devant l'immensité de Paris et l'émerveillement quotidien d'arpenter les berges de la Seine. Une vague d'émotion imprévue a submergé le jeune homme. Au fil des lignes se dessinaient les doutes d'une jeune femme de vingt ans : la peur de décevoir ses parents restés au village, la solitude des soirs d'hiver dans sa modeste chambre mansardée, mais aussi l'immense joie de réussir son premier concours d'institutrice. Madeleine écrivait : J'ai parfois le cœur serré de vous savoir loin, mais chaque matin m'apporte la certitude que ma place est ici, auprès de ces enfants qui ont tant à apprendre. Refermant la boîte avec d'infinies précautions, Mathieu a ressenti un profond soulagement mêlé d'une fierté nouvelle. Les émotions de sa grand-mère faisaient écho à ses propres hésitations actuelles face à ses choix de carrière. Posant le carnet sur son bureau, il a compris que nommer ses peurs et ses joies constituait le plus beau moyen de les apprivoiser et d'avancer sereinement."
