            "type": "lesson",
            "title": "Étape 5 : 📖 Texte intégral — La réunion de copropriété : Querelle autour des panneaux solaires",
            "content": "**La réunion de copropriété : Querelle autour des panneaux solaires**\n\nCe mardi soir, dans le salon de réception de la résidence des Ormes à Lyon, la tension est palpable. L'ordre du jour de l'assemblée générale extraordinaire ne comporte qu'un seul point : l'installation de panneaux solaires photovoltaïques sur le toit-terrasse de l'immeuble. Une question apparemment technique, mais qui met en lumière des visions opposées de l'intérêt commun.\n\nLe président du conseil syndical, Laurent Vaneck, ouvre la séance en déroulant un dossier chiffré. « Chers voisins, nous sommes tous d'accord sur le constat : nos factures d'électricité commune ont augmenté de 35 % en deux ans. L'installation de ces panneaux permettra d'alimenter les ascenseurs et l'éclairage des parties communes, tout en réduisant notre empreinte carbone collective. L'amortissement de l'investissement est garanti en moins de six années grâce aux subventions de l'État. »\n\nPlusieurs copropriétaires hochent la tête en signe d'approbation enthousiaste. Cependant, Madame Delmas, habitante du dernier étage, lève aussitôt la main pour marquer son désaccord. « Je partage entièrement votre volonté d'économiser l'énergie », concède-t-elle avec calme. « En revanche, je m'oppose fermement au devis présenté ce soir. L'entreprise sélectionnée n'offre aucune garantie décennale sur l'étanchéité de la toiture. Si des infiltrations d'eau surviennent l'hiver prochain, ce sont les résidents du quatrième étage qui en subiront immédiatement les conséquences désastreuses ! »\n\nUn murmure parcourt l'assemblée. Loin de s'enfermer dans un affrontement stérile, Laurent Vaneck accueille l'objection : « Votre remarque est parfaitement recevable, Madame Delmas. Il est hors de question de voter un projet sans sécuriser l'étanchéité du toit. » Un consensus se noue alors : le principe des énergies renouvelables est approuvé à l'unanimité, mais le vote définitif des travaux est ajourné le temps d'exiger une garantie décennale complète auprès de l'artisan. L'échange courtois et argumenté a permis d'éviter le blocage.",
