            "title": "Témoignage : Mon engagement au sein de l'épicerie solidaire",
            "content": "« Lorsque j'ai pris ma retraite après quarante ans dans l'enseignement, je ne me voyais pas rester chez moi sans activité sociale. J'ai donc proposé mon aide à l'épicerie solidaire de notre commune.<br><br>Dans notre magasin associatif, les bénéficiaires peuvent acheter des produits alimentaires de première nécessité ainsi que des articles d'hygiène à des tarifs réduits de quatre-vingts pour cent par rapport au commerce traditionnel. Les denrées sont données par des maraîchers locaux et des supermarchés partenaires qui évitent ainsi le gaspillage.<br><br>Mais au-delà de l'aide matérielle, nous avons aménagé un salon d'accueil convivial. Autour d'un café chaud, nous écoutons les récits de personnes confrontées à la solitude ou à des ruptures de vie. Donner deux matinées par semaine me procure un sentiment d'utilité inestimable. »",
            "audioText": "Lorsque j'ai pris ma retraite après quarante ans dans l'enseignement, je ne me voyais pas rester chez moi sans activité sociale. J'ai donc proposé mon aide à l'épicerie solidaire de notre commune. Dans notre magasin associatif, les bénéficiaires peuvent acheter des produits alimentaires de première nécessité ainsi que des articles d'hygiène à des tarifs réduits de quatre-vingts pour cent par rapport au commerce traditionnel. Les denrées sont données par des maraîchers locaux et des supermarchés partenaires qui évitent ainsi le gaspillage. Mais au-delà de l'aide matérielle, nous avons aménagé un salon d'accueil convivial. Autour d'un café chaud, nous écoutons les récits de personnes confrontées à la solitude ou à des ruptures de vie. Donner deux matinées par semaine me procure un sentiment d'utilité inestimable."
