            "title": "Témoignage : Trouver le bon équilibre en télétravail",
            "content": "« Lorsque mon entreprise a généralisé le télétravail à plein temps, j'ai d'abord pensé que c'était la solution idéale. Plus de transports bondés, plus d'horaires rigides, une liberté totale pour organiser ma journée. Cependant, au bout de quelques mois, la frontière entre ma vie privée et mon travail s'est estompée.<br><br>Je me surprenais à répondre à des messages professionnels à vingt-deux heures depuis mon canapé. Mon salon ne ressemblait plus à un espace de détente mais à une extension de mon bureau.<br><br>J'ai dû fixer des règles strictes. Si je ne ferme pas mon ordinateur à dix-huit heures précises, je sais que la soirée sera absorbée par le travail. J'ai aménagé un coin dédié dans une pièce séparée, et j'ai réinstauré une marche matinale avant d'allumer les écrans, pour recréer symboliquement le trajet vers le travail. »",
            "audioText": "Lorsque mon entreprise a généralisé le télétravail à plein temps, j'ai d'abord pensé que cétait la solution idéale. Plus de transports bondés, plus d'horaires rigides, une liberté totale pour organiser ma journée. Cependant, au bout de quelques mois, la frontière entre ma vie privée et mon travail s'est estompée. Je me surprenais à répondre à des messages professionnels à vingt-deux heures depuis mon canapé. Mon salon ne ressemblait plus à un espace de détente mais à une extension de mon bureau. J'ai dû fixer des règles strictes. Si je ne ferme pas mon ordinateur à dix-huit heures précises, je sais que la soirée sera absorbée par le travail. J'ai aménagé un coin dédié dans une pièce séparée, et j'ai réinstauré une marche matinale avant d'allumer les écrans, pour recréer symboliquement le trajet vers le travail."
