            "content": "« C'était un dimanche d'août étouffant en Provence. Depuis plusieurs jours, la chaleur écrasait la garrigue et pas un souffle de vent ne venait agiter les pins. Les cigales chantaient sans répit et nous déjeunions paisiblement à l'ombre d'une tonnelle de vigne.<br><br>Tout à coup, vers seize heures, le ciel a viré au gris plombé en l'espace de dix minutes. Un vent glacial et violent s'est levé soudainement, renversant les verres et emportant les parasols. La pluie s'est abattue en trombes sur la terrasse tandis que des éclairs zébraient la montagne.<br><br>L'orage n'a duré qu'une demi-heure, mais le contraste était saisissant. Auparavant, la nature était endormie sous une torpeur d'été ; désormais, le sol ruisselait et l'air sentait la terre fraîche et le romarin lavé. Cette rupture brutale nous a rappelé la puissance imprévisible de la nature. »",
