            "title": "Témoignage : Comment nous avons réglé le conflit dans notre cour",
            "content": "« Dans notre petit immeuble parisien, la cour pavée était devenue un lieu de discorde permanente. D'un côté, les familles avec de jeunes enfants souhaitaient que ces derniers puissent y jouer au ballon après l'école. De l'autre côté, deux voisins travaillant de nuit et des retraités exigeaient un silence absolu à toute heure de la journée.<br><br>Pendant des mois, les récriminations se faisaient par petits mots acrimonieux collés dans le hall d'entrée. L'ambiance devenait pesante et plus personne ne se saluait dans les escaliers.<br><br>En tant que président bénévole du conseil syndical, j'ai proposé d'organiser une réunion conviviale autour d'un goûter partagé. Chacun a pu exprimer son ressenti sans hausser le ton. Nous avons convenu d'un compromis clair : les enfants ont le droit de jouer dans la cour de seize heures trente à dix-huit heures trente, mais les jeux calmes sont de rigueur le reste du temps. Depuis cet accord, la sérénité est revenue. »",
            "audioText": "Dans notre petit immeuble parisien, la cour pavée était devenue un lieu de discorde permanente. D'un côté, les familles avec de jeunes enfants souhaitaient que ces derniers puissent y jouer au ballon après l'école. De l'autre côté, deux voisins travaillant de nuit et des retraités exigeaient un silence absolu à toute heure de la journée. Pendant des mois, les récriminations se faisaient par petits mots acrimonieux collés dans le hall d'entrée. L'ambiance devenait pesante et plus personne ne se saluait dans les escaliers. En tant que président bénévole du conseil syndical, j'ai proposé d'organiser une réunion conviviale autour d'un goûter partagé. Chacun a pu exprimer son ressenti sans hausser le ton. Nous avons convenu d'un compromis clair : les enfants ont le droit de jouer dans la cour de seize heures trente à dix-huit heures trente, mais les jeux calmes sont de rigueur le reste du temps. Depuis cet accord, la sérénité est revenue."
