            "audioText": "Lancer sa propre maison d'édition tout en conservant son travail de graphiste salarié : tel était le défi que je me suis fixé il y a deux ans. Je ne pouvais pas me permettre de démissionner sans filet financier, car j'avais un emprunt à rembourser. Pendant dix-huit mois, j'ai donc mené deux vies de front. En travaillant méthodiquement tôt le matin et tard le soir, j'ai rédigé les contrats, sélectionné les manuscrits et négocié avec les imprimeurs. Tout s'est fait en parallèle, chaque minute étant mise à profit. C'est précisément en surmontant ces contraintes d'horaires que j'ai acquis une organisation sans faille. Aujourd'hui, mon entreprise éditoriale est viable et autonome. Cette réussite découle directement de la persévérance que j'ai entretenue au cours de cette période intense."
